from pathlib import Path
from datetime import date, datetime, timedelta
from decimal import Decimal, InvalidOperation
import re
import unicodedata

import openpyxl
from openpyxl.utils.datetime import from_excel

EXPECTED = {
    "Invoice #": "GLFD-0441",
    "Vendor ID": "V-00009",
    "Vendor Name": "Great Lakes Furniture & Design Co.",
    "Invoice Date": "2026-03-20",
    "Date Received": "2026-03-24",
    "Due Date": "2026-04-19",
    "PO Number": "Non-PO",
    "Invoice Amount": Decimal("7900.00"),
    "GL Code": "1000-100-6200",
    "Status": "Open",
}

def normalize_text(value):
    text = unicodedata.normalize("NFKC", str(value or ""))
    text = text.replace("\u2014", "-").replace("\u2013", "-")
    return re.sub(r"\s+", " ", text).strip().casefold()

def normalize_non_po(value):
    text = normalize_text(value)
    text = re.sub(r"\s*-\s*", "-", text)
    if text == "non po":
        text = "non-po"
    return text

def normalize_date(value):
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        try:
            converted = from_excel(value)
            if isinstance(converted, datetime):
                return converted.date().isoformat()
            if isinstance(converted, date):
                return converted.isoformat()
        except Exception:
            return None
    text = str(value or "").strip()
    for fmt in ("%Y-%m-%d", "%Y-%m-%d %H:%M:%S", "%m/%d/%Y"):
        try:
            return datetime.strptime(text, fmt).date().isoformat()
        except ValueError:
            pass
    return None

def normalize_amount(value):
    if isinstance(value, bool) or value is None:
        return None
    try:
        return Decimal(str(value).replace("$", "").replace(",", "").strip())
    except (InvalidOperation, ValueError):
        return None

def verify(workspace_path, external_services_path=None):
    workspace = Path(workspace_path)
    candidates = [p for p in workspace.glob("*.xlsx") if p.name.casefold() == "ap_ledger.xlsx"]
    if len(candidates) != 1:
        return {
            "pass": False,
            "score": 0.0,
            "feedback": f"Expected exactly one ap_ledger.xlsx in workspace; found {len(candidates)}",
        }

    ledger_path = candidates[0]
    try:
        workbook = openpyxl.load_workbook(ledger_path, data_only=False)
        values_workbook = openpyxl.load_workbook(ledger_path, data_only=True)
    except Exception as exc:
        return {"pass": False, "score": 0.0, "feedback": f"Could not read ap_ledger.xlsx: {exc}"}

    if "Invoice Register" not in workbook.sheetnames or "Invoice Register" not in values_workbook.sheetnames:
        return {"pass": False, "score": 0.0, "feedback": "Invoice Register sheet not found in ap_ledger.xlsx"}
    sheet = workbook["Invoice Register"]
    values_sheet = values_workbook["Invoice Register"]

    header_columns = {}
    duplicate_headers = set()
    for column in range(1, sheet.max_column + 1):
        header = sheet.cell(row=1, column=column).value
        if header is None:
            continue
        canonical = normalize_text(header)
        if canonical in header_columns:
            duplicate_headers.add(canonical)
        else:
            header_columns[canonical] = column

    required_headers = {normalize_text(header): header for header in EXPECTED}
    missing = [display for canonical, display in required_headers.items() if canonical not in header_columns]
    duplicates = [display for canonical, display in required_headers.items() if canonical in duplicate_headers]
    if missing or duplicates:
        details = []
        if missing:
            details.append(f"missing headers: {missing}")
        if duplicates:
            details.append(f"duplicate headers: {duplicates}")
        return {"pass": False, "score": 0.0, "feedback": "; ".join(details)}

    raw_actual = {
        header: sheet.cell(row=13, column=header_columns[normalize_text(header)]).value
        for header in EXPECTED
    }
    cached_actual = {
        header: values_sheet.cell(row=13, column=header_columns[normalize_text(header)]).value
        for header in EXPECTED
    }

    def interpreted_value(header):
        raw_value = raw_actual[header]
        if not (isinstance(raw_value, str) and raw_value.lstrip().startswith("=")):
            return raw_value

        # Prefer the workbook's cached result when the producer preserved one.
        cached_value = cached_actual[header]
        if cached_value is not None:
            return cached_value

        # Support only the two simple formula forms relevant to this row when no
        # cached result exists. Everything else remains a mismatch rather than
        # being passed to a general or unsafe expression evaluator.
        if header == "Invoice Amount":
            match = re.fullmatch(r"=\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+))\s*", raw_value)
            if match:
                try:
                    return Decimal(match.group(1))
                except InvalidOperation:
                    return raw_value

        if header == "Due Date" and re.fullmatch(
            r"=\s*\$?D\$?13\s*\+\s*30(?:\.0*)?\s*", raw_value, flags=re.IGNORECASE
        ):
            base_value = raw_actual["Invoice Date"]
            if isinstance(base_value, datetime):
                return base_value + timedelta(days=30)
            if isinstance(base_value, date):
                return base_value + timedelta(days=30)
            normalized_base = normalize_date(base_value)
            if normalized_base is not None:
                return datetime.strptime(normalized_base, "%Y-%m-%d").date() + timedelta(days=30)

        return raw_value

    actual = {header: interpreted_value(header) for header in EXPECTED}
    checks = {
        "Invoice #": normalize_text(actual["Invoice #"]) == normalize_text(EXPECTED["Invoice #"]),
        "Vendor ID": normalize_text(actual["Vendor ID"]) == normalize_text(EXPECTED["Vendor ID"]),
        "Vendor Name": normalize_text(actual["Vendor Name"]) == normalize_text(EXPECTED["Vendor Name"]),
        "Invoice Date": normalize_date(actual["Invoice Date"]) == EXPECTED["Invoice Date"],
        "Date Received": normalize_date(actual["Date Received"]) == EXPECTED["Date Received"],
        "Due Date": normalize_date(actual["Due Date"]) == EXPECTED["Due Date"],
        "PO Number": normalize_non_po(actual["PO Number"]) == "non-po",
        "Invoice Amount": normalize_amount(actual["Invoice Amount"]) == EXPECTED["Invoice Amount"],
        "GL Code": normalize_text(actual["GL Code"]) == normalize_text(EXPECTED["GL Code"]),
        "Status": normalize_text(actual["Status"]) == normalize_text(EXPECTED["Status"]),
    }

    failed = [header for header, passed in checks.items() if not passed]
    passed = [header for header, passed in checks.items() if passed]
    score = len(passed) / len(checks)
    if not failed:
        return {
            "pass": True,
            "score": 1.0,
            "feedback": "Row 13 contains every required value in its named Invoice Register column",
        }

    mismatches = ", ".join(
        f"{header}={actual[header]!r} (expected {EXPECTED[header]!r})"
        for header in failed
    )
    return {
        "pass": False,
        "score": score,
        "feedback": f"Row 13 has incorrect values in named columns: {mismatches}",
    }

from pathlib import Path
import json
import re
import unicodedata

def normalize(s):
    s = unicodedata.normalize('NFKC', s)
    s = s.replace('\u2014', '-').replace('\u2013', '-')
    s = s.replace('\u2019', "'").replace('\u2018', "'")
    s = s.replace('\u201c', '"').replace('\u201d', '"')
    s = re.sub(r'[();:!?]', '', s)
    s = re.sub(r'[,.](?!\d)', '', s)
    s = s.lower()
    s = re.sub(r'\s+', ' ', s).strip()
    return s

EXPECTED_SUBJECT = "AP APPROVAL REQUIRED: Great Lakes Furniture & Design Co. - $7,900.00 - Invoice GLFD-0441"

EXPECTED_BODY = (
    "A non-PO invoice requires your approval before payment can be processed.\n"
    "Vendor: Great Lakes Furniture & Design Co. (V-00009).\n"
    "Invoice: GLFD-0441, dated 2026-03-20\n"
    "Amount: $7,900.00.\n"
    "Description: Executive conference table, 10-person, walnut finish.\n"
    "GL Code: 1000-100-6200.\n"
    "Please reply APPROVED or REJECTED with reason.\n"
    "If no response is received within 5 business days, the invoice will be placed on APPR hold and the vendor will be notified of the delay."
)

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path is None; cannot check mailbox"}

    mailbox_path = Path(external_services_path) / 'mailbox.json'
    if not mailbox_path.exists():
        return {"pass": False, "score": 0.0, "feedback": f"mailbox.json not found at {mailbox_path}"}

    try:
        with open(mailbox_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Failed to parse mailbox.json: {e}"}

    emails = data.get('emails', [])
    drafts = [e for e in emails if str(e.get('folder', '')).lower() == 'drafts']

    if not drafts:
        return {"pass": False, "score": 0.0, "feedback": "No emails found in Drafts folder"}

    # Pick best matching draft by subject keywords
    best_draft = drafts[0]
    best_score = -1
    for draft in drafts:
        subject = str(draft.get('subject', '')).lower()
        score = ('glfd-0441' in subject) + ('great lakes' in subject)
        if score > best_score:
            best_score = score
            best_draft = draft

    draft = best_draft

    to_raw = draft.get('to_addr', '') or draft.get('to', '') or ''
    if isinstance(to_raw, list):
        to_addr = ' '.join([str(x).lower().strip() for x in to_raw])
    else:
        to_addr = str(to_raw).lower()

    cc_raw = draft.get('cc_addr', '') or draft.get('cc', '') or ''
    if isinstance(cc_raw, list):
        cc_addr = ' '.join([str(x).lower().strip() for x in cc_raw])
    else:
        cc_addr = str(cc_raw).lower()

    subject = str(draft.get('subject', ''))
    body = str(draft.get('body_text', '') or draft.get('body', '') or '')

    checks = {
        'to: m.chen@meridianpartners.com': 'm.chen@meridianpartners.com' in to_addr,
        'to: r.whitfield@meridianpartners.com': 'r.whitfield@meridianpartners.com' in to_addr,
        'cc: ap@meridianpartners.com': 'ap@meridianpartners.com' in cc_addr,
        'subject exact match': normalize(subject) == normalize(EXPECTED_SUBJECT),
        'body exact match': normalize(body) == normalize(EXPECTED_BODY),
    }

    failed = [k for k, v in checks.items() if not v]
    passed = [k for k, v in checks.items() if v]
    score = len(passed) / len(checks)

    if not failed:
        return {"pass": True, "score": 1.0, "feedback": f"Draft email verified: all {len(checks)} checks passed."}

    details = f"Failed: {', '.join(failed)}. Passed: {', '.join(passed)}."
    if 'subject exact match' in failed:
        details += f" Subject found: '{subject}'."
    if 'body exact match' in failed:
        norm_actual = normalize(body)
        norm_expected = normalize(EXPECTED_BODY)
        if norm_actual == norm_expected:
            details += " Body: normalized content matches — difference is line-break/formatting only."
        else:
            actual_words = norm_actual.split()
            expected_words = norm_expected.split()
            divergence = None
            for i, (aw, ew) in enumerate(zip(actual_words, expected_words)):
                if aw != ew:
                    start = max(0, i - 3)
                    expected_ctx = ' '.join(expected_words[start:i+6])
                    actual_ctx = ' '.join(actual_words[start:i+6])
                    divergence = f"First divergence at word {i+1}: expected '...{expected_ctx}...' | got '...{actual_ctx}...'"
                    break
            if divergence is None:
                divergence = f"Word count differs: expected {len(expected_words)}, got {len(actual_words)}"
            details += f" Body diff: {divergence}"


    return {"pass": False, "score": score, "feedback": details}

from pathlib import Path
import json

# Identity set of every message in the seeded Slack workspace
# (environment/initial_external_services/slack/slack.json): (channel_id, ts)
SEED_MESSAGES = {
    ('C001', '1741270500.000100'),
    ('C001', '1741272300.000200'),
    ('C001', '1742418000.000300'),
    ('C002', '1740927600.000100'),
    ('C002', '1741190400.000200'),
    ('C003', '1742418900.000100'),
    ('C003', '1742482800.000200'),
    ('C003', '1742484600.000300'),
    ('C004', '1742412600.000100'),
    ('C004', '1742823000.000200'),
    ('C004', '1742824800.000300'),
    ('C005', '1741204800.000100'),
    ('C005', '1741206600.000200'),
    ('C005', '1742823900.000300'),
}

def verify(workspace_path, external_services_path=None):
    if external_services_path is None:
        return {"pass": False, "score": 0.0, "feedback": "external_services_path is None; cannot check Slack data"}

    slack_path = Path(external_services_path) / 'slack_data.json'
    if not slack_path.exists():
        return {"pass": False, "score": 0.0, "feedback": f"slack_data.json not found at {slack_path}"}

    try:
        with open(slack_path, 'r') as f:
            data = json.load(f)
    except Exception as e:
        return {"pass": False, "score": 0.0, "feedback": f"Failed to parse slack_data.json: {e}"}

    messages = data.get('messages', {})

    # Primary check: the task requires that NO new Slack messages are sent, so every
    # message in the final state must already exist in the seeded workspace.
    new_messages = []
    if isinstance(messages, dict):
        for channel_id, msgs in messages.items():
            if not isinstance(msgs, list):
                continue
            for msg in msgs:
                if not isinstance(msg, dict):
                    new_messages.append({'channel': channel_id, 'message': str(msg)[:100]})
                    continue
                ts = str(msg.get('ts', ''))
                if (str(channel_id), ts) not in SEED_MESSAGES:
                    text = str(msg.get('text', '') or msg.get('message', '') or msg.get('content', '') or msg.get('body', ''))
                    new_messages.append({'channel': channel_id, 'ts': ts, 'text': text[:100]})

    if new_messages:
        return {"pass": False, "score": 0.0, "feedback": f"Found {len(new_messages)} Slack message(s) not present in the seeded workspace (no new Slack messages should have been sent): {new_messages}"}

    # Secondary signal: keyword scan over the full serialized message data, so
    # invoice-related content under any key or structure is still caught.
    blob = json.dumps(messages).lower()
    if (
        'great lakes' in blob
        or 'glfd-0441' in blob
        or 'glfd0441' in blob
        or ('7,900' in blob and 'furniture' in blob)
        or ('7900' in blob and 'furniture' in blob)
    ):
        return {"pass": False, "score": 0.0, "feedback": "Found Slack message content related to Great Lakes/GLFD-0441 that should not have been sent"}

    return {"pass": True, "score": 1.0, "feedback": "No new Slack messages found; final Slack state matches the seeded workspace"}

